// Globals of a page that hosts a VM, shared by the host's scripts, the web
// gate's relay and app, and the surfaces. site.js is generated by
// tools/build.mjs; the window properties are set by the host's scripts.
export {};

declare global {
  /** The app's deployment config (site.js, written by tools/build.mjs). */
  var SITE_CONFIG: {
    /** Deployment origins, from IDE_URL / GATE_URL at build time (absent when built without them). */
    ideUrl?: string;
    gateUrl?: string;
    /** Preview origins, e.g. "https://{id}.preview.example.com/" (PREVIEW_URL). */
    previewUrl?: string;
    /** Or a fixed list of preview origins, handed out as previews open (PREVIEW_ORIGINS). */
    previewOrigins?: string[];
    /** false: the app has no gate, so the VM has no network (app config `gate: "none"`). */
    gate?: false;
    /** false: the app has previews off. */
    previews?: false;
    /** The playground to start in when the URL names none (app config `start`). */
    start?: string;
    /** The app's surfaces: path from the site root ("" for the root) → surface name. */
    surfaces?: Record<string, string>;
    /** The site root's URL, worked out by site.js from its own address. */
    root?: string;
  } | undefined;
  /** Where the web gate is served, if set by hand (SITE_CONFIG.gateUrl wins). */
  var GATE_URL: string | undefined;

  interface Window {
    /** BroadcastChannel name of this tab's gate relay (set by gate-relay.js, read by runtime-host.js). */
    __vmGateChannel?: string;
    /** BroadcastChannel name of this tab's VM runtime (set by runtime-host.js, read by surfaces). */
    __vmRuntimeChannel?: string;
    /** Where to open a preview, with "{port}" for the guest port (set by runtime-host.js; undefined: no preview origin). */
    __vmPreviewUrl?: string;
  }
}
